const ctx = $json;
const waId = $('Disparado por webhook/recovery').item.json.waId;
let buffer = [];
try { buffer = JSON.parse($('Leer buffer').item.json.bufferRaw || '[]'); } catch (e) {}

const identity = __AGENT_IDENTITY__;
const rules = __AGENT_RULES__;
const tools = __AGENT_TOOLS__;

const capa3 = [
  '## Datos del negocio (capa 3)',
  'Negocio: ' + JSON.stringify(ctx.business || {}),
  'Servicios: ' + JSON.stringify(ctx.services || []),
  'Profesionales: ' + JSON.stringify(ctx.professionals || []),
  'Telefono de la clienta (para las herramientas): ' + waId,
  'Consentimiento ya mostrado: ' + (ctx.consent_shown_at ? 'si' : 'no'),
  ctx.conversation_summary ? ('Resumen de la conversacion: ' + ctx.conversation_summary) : ''
].filter(Boolean).join('\n');

const system = identity + '\n\n' + rules + '\n\n' + capa3;

const history = Array.isArray(ctx.history) ? ctx.history : [];
const messages = history.map(h => ({
  role: h.direction === 'outbound' ? 'assistant' : 'user',
  content: h.content || ''
}));
messages.push({ role: 'user', content: buffer.map(m => m.text).filter(Boolean).join('\n') || '(mensaje sin texto)' });

return [{ json: { system, messages, tools, ctx, waId, buffer } }];

const provider = '__MODEL_PROVIDER__';
const model = '__MODEL_NAME__';
const src = $input.first().json;
const system = src.system || '';
const messages = Array.isArray(src.messages) ? src.messages : [];
const tools = Array.isArray(src.tools) ? src.tools : [];

function sanearParaGemini(schema) {
  const s = JSON.parse(JSON.stringify(schema || {}));
  const walk = (o) => {
    if (!o || typeof o !== 'object') return;
    delete o.additionalProperties; delete o.$comment; delete o.minLength; delete o.minItems;
    if (o.format === 'e164' || o.format === 'uuid') delete o.format;
    if (o.properties) Object.values(o.properties).forEach(walk);
    if (o.items) walk(o.items);
  };
  walk(s); return s;
}

let url, method = 'POST', headers = {}, body = {};
if (provider === 'claude') {
  url = 'https://api.anthropic.com/v1/messages';
  headers = { 'anthropic-version': '2023-06-01' };
  body = { model, max_tokens: 1024, temperature: 0.3, system,
    messages: messages.map(m => ({ role: m.role === 'assistant' ? 'assistant' : 'user', content: m.content })),
    tools: tools.map(t => ({ name: t.name, description: t.description, input_schema: t.parameters })) };
} else {
  url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`;
  body = { system_instruction: { parts: [{ text: system }] },
    contents: messages.map(m => ({ role: m.role === 'assistant' ? 'model' : 'user', parts: [{ text: String(m.content) }] })),
    tools: [{ function_declarations: tools.map(t => ({ name: t.name, description: t.description, parameters: sanearParaGemini(t.parameters) })) }],
    generationConfig: { temperature: 0.3 } };
}
return [{ json: { url, method, headers, body, provider, model, _ctx: src.ctx, _waId: src.waId, _buffer: src.buffer, _system: system, _tools: tools, _messages: messages } }];

const provider = '__MODEL_PROVIDER__';
const resp = $input.first().json;
let text = ''; const toolCalls = []; let usage = { in: 0, out: 0 };
if (provider === 'claude') {
  for (const b of (resp.content || [])) {
    if (b.type === 'text') text += b.text;
    if (b.type === 'tool_use') toolCalls.push({ id: b.id, name: b.name, args: b.input || {} });
  }
  usage = { in: resp.usage?.input_tokens || 0, out: resp.usage?.output_tokens || 0 };
} else {
  for (const p of (resp.candidates?.[0]?.content?.parts || [])) {
    if (p.text) text += p.text;
    if (p.functionCall) toolCalls.push({ id: null, name: p.functionCall.name, args: p.functionCall.args || {} });
  }
  usage = { in: resp.usageMetadata?.promptTokenCount || 0, out: resp.usageMetadata?.candidatesTokenCount || 0 };
}
const prev = $('Modelo · Construir request').item.json;
return [{ json: { text: text.trim(), toolCalls, usage, provider, model: '__MODEL_NAME__',
  _ctx: prev._ctx, _waId: prev._waId, _buffer: prev._buffer, _system: prev._system, _tools: prev._tools, _messages: prev._messages } }];

const norm = $json;
const tc = norm.toolCalls[0];
const a = tc.args || {};
const waId = norm._waId;
let query = '', params = [];
switch (tc.name) {
  case 'consultar_servicios':
    query = "SELECT json_agg(json_build_object('nombre',name,'precio',price,'duracion_min',duration_minutes) ORDER BY name) AS data FROM services WHERE active";
    break;
  case 'consultar_horarios':
    query = "SELECT json_agg(json_build_object('profesional',p.name,'dia_semana',sc.day_of_week,'desde',sc.time_from::text,'hasta',sc.time_to::text) ORDER BY p.name, sc.day_of_week) AS data FROM schedule sc JOIN professionals p ON p.id=sc.professional_id WHERE p.active";
    break;
  case 'consultar_disponibilidad':
    query = "WITH pedidos AS (SELECT DISTINCT lower(value) AS n FROM json_array_elements_text($2::json) AS value), ids AS (SELECT array_agg(s.id) AS arr, count(*) AS c FROM services s WHERE lower(s.name) IN (SELECT n FROM pedidos) AND s.active) SELECT json_agg(json_build_object('profesional',professional_name,'inicio',slot_start,'fin',slot_end) ORDER BY slot_start) AS data FROM get_availability($1::date, (SELECT CASE WHEN c = (SELECT count(*) FROM pedidos) THEN arr END FROM ids), (SELECT id FROM professionals WHERE lower(name)=lower(NULLIF($3,'')) AND active LIMIT 1))";
    params = [a.fecha || '', JSON.stringify(Array.isArray(a.servicios) ? a.servicios : (a.servicio ? [a.servicio] : [])), a.profesional || ''];
    break;
  case 'consultar_turnos_cliente':
    query = "SELECT json_agg(json_build_object('turno_id',ap.id,'inicio',ap.starts_at,'profesional',p.name) ORDER BY ap.starts_at) AS data FROM appointments ap JOIN clients c ON c.id=ap.client_id JOIN professionals p ON p.id=ap.professional_id WHERE c.phone=$1 AND ap.status='confirmed' AND ap.starts_at > now()";
    params = [waId];
    break;
  case 'crear_turno':
    query = "WITH pedidos AS (SELECT DISTINCT value AS nombre, lower(value) AS n FROM json_array_elements_text($2::json) AS value), resueltos AS (SELECT p.nombre, s.id FROM pedidos p LEFT JOIN services s ON lower(s.name) = p.n AND s.active), faltan AS (SELECT string_agg(nombre, ', ') AS lista FROM resueltos WHERE id IS NULL) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM pedidos) THEN 'ERROR: no indicaste ningún servicio' WHEN (SELECT lista FROM faltan) IS NOT NULL THEN 'ERROR: no encontré el servicio ' || (SELECT lista FROM faltan) ELSE book_appointment((SELECT id FROM clients WHERE phone=$1), (SELECT id FROM professionals WHERE lower(name)=lower($3) AND active LIMIT 1), (SELECT array_agg(id) FROM resueltos), $4::timestamptz)::text END AS data";
    params = [waId, JSON.stringify(a.servicios || []), a.profesional || '', a.hora_inicio || ''];
    break;
  case 'cancelar_turno':
    query = "WITH chk AS (SELECT allowed, reason FROM can_cancel($1)), done AS (SELECT cancel_appointment($1,false) WHERE (SELECT allowed FROM chk)) SELECT CASE WHEN (SELECT allowed FROM chk) THEN (SELECT 'cancelado'::text FROM done) ELSE (SELECT reason FROM chk) END AS data";
    params = [a.turno_id || ''];
    break;
  case 'modificar_turno':
    query = "WITH chk AS (SELECT allowed, reason FROM can_cancel($1)), old AS (SELECT client_id, professional_id, (SELECT array_agg(service_id) FROM appointment_services WHERE appointment_id=$1) AS svc FROM appointments WHERE id=$1), done AS (SELECT cancel_appointment($1,false) WHERE (SELECT allowed FROM chk)), rebook AS (SELECT book_appointment(old.client_id, old.professional_id, old.svc, $2::timestamptz) AS new_id FROM old, done WHERE (SELECT allowed FROM chk)) SELECT CASE WHEN (SELECT allowed FROM chk) THEN json_build_object('turno_id',(SELECT new_id FROM rebook),'estado','reprogramado')::text ELSE (SELECT reason FROM chk) END AS data";
    params = [a.turno_id || '', a.nueva_hora || ''];
    break;
  case 'sumar_lista_espera':
    query = "INSERT INTO waitlist (client_id, service_id, professional_id, date_from, date_to) SELECT (SELECT id FROM clients WHERE phone=$1), (SELECT id FROM services WHERE lower(name)=lower($2) AND active LIMIT 1), (SELECT id FROM professionals WHERE lower(name)=lower(NULLIF($3,'')) AND active LIMIT 1), $4::date, $5::date RETURNING json_build_object('waitlist_id',id,'estado','anotada')::text AS data";
    params = [waId, a.servicio || '', a.profesional || '', a.fecha_desde || '', a.fecha_hasta || ''];
    break;
  case 'derivar_a_humano':
    return [{ json: { handoff: true, toolName: tc.name, razon: a.razon || 'sin motivo', categoria: a.categoria || 'fuera_de_alcance', _passthru: norm } }];
  default:
    return [{ json: { toolName: tc.name, error: 'herramienta desconocida', _passthru: norm } }];
}
return [{ json: { toolName: tc.name, query, queryParams: params, handoff: false, _passthru: norm } }];

const armar = $('Ejecutar herramienta (armar)').item.json;
const norm = armar._passthru;
const tc = norm.toolCalls[0];
let resultData;
if ($input.first().json.error) resultData = { error: String($input.first().json.error) };
else resultData = $input.first().json.data !== undefined ? $input.first().json.data : $input.first().json;

const messages = [
  ...norm._messages,
  { role: 'assistant', content: `Llamé a la herramienta ${tc.name} con ${JSON.stringify(tc.args)}.` },
  { role: 'user', content: `Resultado de ${tc.name}: ${JSON.stringify(resultData)}. Redactá la respuesta para la clienta en base a esto. No muestres IDs ni JSON.` }
];
return [{ json: { system: norm._system, messages, tools: norm._tools, _ctx: norm._ctx, _waId: norm._waId, _buffer: norm._buffer } }];

const provider = '__MODEL_PROVIDER__';
const model = '__MODEL_NAME__';
const src = $input.first().json;
const system = src.system || '';
const messages = Array.isArray(src.messages) ? src.messages : [];
const tools = Array.isArray(src.tools) ? src.tools : [];
function sanearParaGemini(schema){const s=JSON.parse(JSON.stringify(schema||{}));const walk=(o)=>{if(!o||typeof o!=='object')return;delete o.additionalProperties;delete o.$comment;delete o.minLength;delete o.minItems;if(o.format==='e164'||o.format==='uuid')delete o.format;if(o.properties)Object.values(o.properties).forEach(walk);if(o.items)walk(o.items);};walk(s);return s;}
