  body={model,max_tokens:1024,temperature:0.3,system,messages:messages.map(m=>({role:m.role==='assistant'?'assistant':'user',content:m.content})),tools:tools.map(t=>({name:t.name,description:t.description,input_schema:t.parameters}))};
