}
return [{ json: { url, method, headers, body, provider } }];

const provider = '__MODEL_PROVIDER__';
const resp = $input.first().json;
let text = '';
if (provider === 'claude') { for (const b of (resp.content||[])) if (b.type==='text') text += b.text; }
else { for (const p of (resp.candidates?.[0]?.content?.parts||[])) if (p.text) text += p.text; }
const armar = $('Ejecutar herramienta (armar)').item.json;
return [{ json: { finalText: text.trim() || 'Listo.', handoff: false, toolName: armar.toolName || null } }];

const r = $json;
const ctx = $('Construir contexto modelo').item.json.ctx || {};
const waId = $('Disparado por webhook/recovery').item.json.waId;
let text = r.finalText || 'Listo.';
if (!ctx.consent_shown_at) {
  text = 'Al continuar aceptás recibir mensajes automáticos del local. Escribí BAJA en cualquier momento para dejar de recibirlos.\n\n' + text;
}
const waPayload = { messaging_product: 'whatsapp', to: waId, type: 'text', text: { body: text } };
return [{ json: {
  waPayload,
  conversationId: ctx.conversation_id,
  clientId: ctx.client_id,
  needsConsent: !ctx.consent_shown_at,
  handoff: !!r.handoff, razon: r.razon || null, categoria: r.categoria || null,
  finalText: text, waId
} }];

