UPDATE conversations SET last_outbound_at = now() WHERE id = $1;
UPDATE clients SET consent_shown_at = now() WHERE id = $2 AND consent_shown_at IS NULL;
INSERT INTO messages (conversation_id, direction, content)
SELECT $1::uuid, 'inbound', value->>'text' FROM jsonb_array_elements($3::jsonb) AS value
UNION ALL SELECT $1::uuid, 'outbound', $4;
